package com.rappistream.orderprocessor.infrastructure.health;  import org.springframework.amqp.rabbit.listener.RabbitListenerEndpointRegistry; import org.springframework.boot.actuate.health.Health; import org.springframework.boot.actuate.health.HealthIndicator; import org.springframework.stereotype.Component;  @Component("rabbitListener") public class RabbitListenerHealthIndicator implements HealthIndicator {      private final RabbitListenerEndpointRegistry registry;      public RabbitListenerHealthIndicator(RabbitListenerEndpointRegistry registry) {         this.registry = registry;     }      @Override     public Health health() {         boolean running = !registry.getListenerContainers().isEmpty()                 && registry.getListenerContainers().stream()                 .allMatch(c -> c.isRunning());         if (running) {             return Health.up().withDetail("containers", registry.getListenerContainers().size()).build();         }         return Health.down().withDetail("containers", registry.getListenerContainers().size()).build();     } }
